import { mountDashboard, icon } from './dashboard.mjs';
const uploadIcon='<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M12 16V3m-6 6 6-6 6 6M3 15v6h18v-6"/></svg>';
export function botsHTML(){return '<div class="bots-page"><section class="bots-panel bot-upload" aria-labelledby="upload-title"><h1 id="upload-title">'+uploadIcon+' UPLOAD TRADING BOT</h1><div class="bot-upload-body"><label class="bot-dropzone" id="bot-dropzone" for="bot-file"><span class="bot-empty-icon">'+uploadIcon+'</span><strong>Drag &amp; drop your bot file here</strong><span>or click to browse</span><small>Supports .py, .js, .ts, .json, .zip files</small><input id="bot-file" type="file" accept=".py,.js,.ts,.json,.zip"><span id="bot-file-name" role="status">No file selected</span></label><button type="button" class="deposit-continue" id="bot-upload">'+icon('bots')+' Upload Trading Bot</button><p class="transfer-caption">Placeholder only. Files stay on your device and are never uploaded or executed.</p><p id="bot-upload-feedback" role="status" class="transfer-placeholder-note" hidden></p></div></section><div class="bots-divider"><span>OR</span></div><section class="bots-panel bot-passkey" aria-labelledby="passkey-title"><h2 id="passkey-title"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="8" cy="8" r="5"/><path d="m12 12 9 9m-5-5 3-3m-1 5 3-3"/></svg> ACTIVATE WITH PASSKEY</h2><p>Already have a trading bot passkey? Enter it below to activate your bot instantly.</p><form id="bot-passkey-form"><label class="sr-only" for="bot-passkey">Trading bot passkey placeholder</label><input id="bot-passkey" placeholder="Enter a demo trading bot passkey" autocomplete="off" maxlength="100"><button class="deposit-continue" type="submit">'+icon('bolt')+' Submit Passkey</button></form><p class="transfer-caption">Activation placeholder. Use sample text only. No passkey is sent or saved.</p><p id="bot-passkey-feedback" role="status" class="transfer-placeholder-note" hidden></p></section><section class="bots-panel bot-settings" aria-labelledby="bot-settings-title"><h2 id="bot-settings-title">'+icon('settings')+' Bot Settings</h2><p>Configure your bot before starting</p><div class="bot-settings-grid"><div class="transfer-field"><label for="bot-amount">Trade Amount ($)</label><input id="bot-amount" type="number" value="10" min="1" step="0.01"></div><div class="transfer-field"><label for="bot-interval">Trade Interval</label><select id="bot-interval"><option>1 minute</option><option>5 minutes</option><option>15 minutes</option><option>1 hour</option></select></div><div class="transfer-field"><label for="bot-asset">Trading Asset</label><select id="bot-asset"><option>EUR/USD</option><option>BTC/USDT</option><option>ETH/USDT</option><option>GBP/USD</option></select></div></div><p class="transfer-caption">Settings preview only. No strategy is running.</p></section><section class="bots-panel my-bots" aria-labelledby="my-bots-title"><h2 id="my-bots-title">'+icon('bots')+' My Bots (0)</h2><div class="bot-empty"><span class="bot-empty-icon">'+icon('bots')+'</span><p>No bots added yet</p></div></section></div>';}
export function mountBots(root,options={}){mountDashboard(root,{...options,view:'bots',mainHTML:botsHTML()});const input=root.querySelector('#bot-file'),zone=root.querySelector('#bot-dropzone'),name=root.querySelector('#bot-file-name');let selected=false;function showFile(file){selected=!!file;name.textContent=file?file.name:'No file selected';}input.onchange=()=>showFile(input.files[0]);zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragging');};zone.ondragleave=()=>zone.classList.remove('dragging');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragging');showFile(e.dataTransfer.files[0]);};root.querySelector('#bot-upload').onclick=()=>{const msg=root.querySelector('#bot-upload-feedback');msg.hidden=false;msg.textContent=selected?'Upload placeholder. Your file has not been uploaded and no bot was added.':'Choose a sample file to preview its name. Uploading is not connected.';};root.querySelector('#bot-passkey-form').onsubmit=e=>{e.preventDefault();root.querySelector('#bot-passkey').value='';const msg=root.querySelector('#bot-passkey-feedback');msg.hidden=false;msg.textContent='Activation placeholder. No passkey was submitted and no bot was activated.';};window.scrollTo(0,0);}
